  assign when_WeBattleIntegerALU_l47 = (io_op == ALUOpType_SLT);
  assign when_WeBattleIntegerALU_l49 = (io_op == ALUOpType_SLTU);
  always @(*) begin
    shiftResult = (io_src1 <<< io_shiftAmount);
    case(io_op)
      ALUOpType_SRL_1 : begin
        shiftResult = (io_src1 >>> io_shiftAmount);
      end
      ALUOpType_SRA_1 : begin
        shiftResult = _zz_shiftResult;
      end
      default : begin
      end
    endcase
  end

  always @(*) begin
    case(io_op)
      ALUOpType_ADD, ALUOpType_ADDU, ALUOpType_SUB, ALUOpType_SUBU, ALUOpType_LU12I, ALUOpType_PCADDI, ALUOpType_PCADDU12I : begin
        io_result = arithmeticResult;
      end
      ALUOpType_AND_1, ALUOpType_OR_1, ALUOpType_XOR_1, ALUOpType_NOR_1 : begin
        io_result = logicResult;
      end
      ALUOpType_SLT, ALUOpType_SLTU : begin
        io_result = compareResult;
      end
      ALUOpType_SLL_1, ALUOpType_SRL_1, ALUOpType_SRA_1 : begin
        io_result = shiftResult;
      end
      default : begin
        io_result = 32'h0;
      end
    endcase
  end


endmodule

module WeBattleCheckpointRAS (
  output     [2:0]    io_checkpoint,
  input               io_speculativeFire,
  input               io_speculativeCall,
  input               io_speculativeReturn,
  input      [29:0]   io_speculativeReturnWord,
  output reg          io_prediction_valid,
  output reg [31:0]   io_prediction_payload,
  input               io_repairValid,
  input               io_repairMispredict,
  input               io_repairCall,
  input               io_repairReturn,
  input      [2:0]    io_repairCheckpoint,
  input      [29:0]   io_repairPcWord,
  input               aclk,
  input               aresetn
);

  reg        [29:0]   _zz_io_prediction_payload;
  reg        [29:0]   returnWords_0;
  reg        [29:0]   returnWords_1;
  reg        [29:0]   returnWords_2;
  reg        [29:0]   returnWords_3;
  reg        [29:0]   returnWords_4;
  reg        [29:0]   returnWords_5;
  reg        [29:0]   returnWords_6;
  reg        [29:0]   returnWords_7;
  reg        [2:0]    nextFree;
  wire       [2:0]    speculativeReturnIndex;
  wire                when_WeBattleCheckpointRAS_l52;
  wire       [7:0]    _zz_1;
  wire       [29:0]   _zz_returnWords_0;
  wire       [7:0]    _zz_2;

  always @(*) begin
    case(speculativeReturnIndex)
      3'b000 : _zz_io_prediction_payload = returnWords_0;
      3'b001 : _zz_io_prediction_payload = returnWords_1;
      3'b010 : _zz_io_prediction_payload = returnWords_2;
      3'b011 : _zz_io_prediction_payload = returnWords_3;
      3'b100 : _zz_io_prediction_payload = returnWords_4;
      3'b101 : _zz_io_prediction_payload = returnWords_5;
      3'b110 : _zz_io_prediction_payload = returnWords_6;
      default : _zz_io_prediction_payload = returnWords_7;
    endcase
  end

  assign io_checkpoint = nextFree;
  always @(*) begin
    io_prediction_valid = 1'b0;
    if(when_WeBattleCheckpointRAS_l52) begin
      io_prediction_valid = 1'b1;
    end
  end

  always @(*) begin
    io_prediction_payload = 32'bxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx;
    if(when_WeBattleCheckpointRAS_l52) begin
      io_prediction_payload = {_zz_io_prediction_payload,2'b00};
    end
  end

  assign speculativeReturnIndex = (nextFree - 3'b001);
  assign when_WeBattleCheckpointRAS_l52 = ((io_speculativeFire && (! io_speculativeCall)) && io_speculativeReturn);
  assign _zz_1 = ({7'd0,1'b1} <<< io_repairCheckpoint);
  assign _zz_returnWords_0 = (io_repairPcWord + 30'h00000001);
  assign _zz_2 = ({7'd0,1'b1} <<< nextFree);
  always @(posedge aclk or negedge aresetn) begin
    if(!aresetn) begin
      returnWords_0 <= 30'h07000000;
      returnWords_1 <= 30'h07000000;
      returnWords_2 <= 30'h07000000;
      returnWords_3 <= 30'h07000000;
      returnWords_4 <= 30'h07000000;
      returnWords_5 <= 30'h07000000;
      returnWords_6 <= 30'h07000000;
      returnWords_7 <= 30'h07000000;
      nextFree <= 3'b000;
    end else begin
      if(io_repairValid) begin
        if(io_repairMispredict) begin
          if(io_repairCall) begin
            if(_zz_1[0]) begin
              returnWords_0 <= _zz_returnWords_0;
            end
            if(_zz_1[1]) begin
              returnWords_1 <= _zz_returnWords_0;
            end
            if(_zz_1[2]) begin
              returnWords_2 <= _zz_returnWords_0;
            end
            if(_zz_1[3]) begin
              returnWords_3 <= _zz_returnWords_0;
            end
            if(_zz_1[4]) begin
              returnWords_4 <= _zz_returnWords_0;
            end
            if(_zz_1[5]) begin
              returnWords_5 <= _zz_returnWords_0;
            end
            if(_zz_1[6]) begin
              returnWords_6 <= _zz_returnWords_0;
            end
            if(_zz_1[7]) begin
              returnWords_7 <= _zz_returnWords_0;
            end
            nextFree <= (io_repairCheckpoint + 3'b001);
          end else begin
            if(io_repairReturn) begin
              nextFree <= (io_repairCheckpoint - 3'b001);
            end else begin
              nextFree <= io_repairCheckpoint;
            end
          end
        end else begin
          nextFree <= io_repairCheckpoint;
        end
      end else begin
        if(io_speculativeFire) begin
          if(io_speculativeCall) begin
            if(_zz_2[0]) begin
              returnWords_0 <= io_speculativeReturnWord;
            end
            if(_zz_2[1]) begin
              returnWords_1 <= io_speculativeReturnWord;
            end
            if(_zz_2[2]) begin
              returnWords_2 <= io_speculativeReturnWord;
            end
            if(_zz_2[3]) begin
              returnWords_3 <= io_speculativeReturnWord;
            end
            if(_zz_2[4]) begin
              returnWords_4 <= io_speculativeReturnWord;
            end
            if(_zz_2[5]) begin
              returnWords_5 <= io_speculativeReturnWord;
            end
            if(_zz_2[6]) begin
              returnWords_6 <= io_speculativeReturnWord;
            end
            if(_zz_2[7]) begin
              returnWords_7 <= io_speculativeReturnWord;
            end
            nextFree <= (nextFree + 3'b001);
          end else begin
            if(io_speculativeReturn) begin
              nextFree <= (nextFree - 3'b001);
            end
          end
        end
      end
    end
  end


endmodule

