module SDPRAM_3 (
  input               aclk,
  input               aresetn,
  input               io_read_cmd_valid,
  input      [9:0]    io_read_cmd_payload,
  output     [31:0]   io_read_rsp,
  input               io_write_valid,
  input      [9:0]    io_write_payload_address,
  input      [31:0]   io_write_payload_data,
  input      [3:0]    io_writeMask
);

  wire                mem_rstb;
  wire       [31:0]   mem_doutb;
  wire                mem_sbiterrb;
  wire                mem_dbiterrb;

  xpm_memory_sdpram #(
    .ADDR_WIDTH_A(10),
    .ADDR_WIDTH_B(10),
    .AUTO_SLEEP_TIME(0),
    .BYTE_WRITE_WIDTH_A(8),
    .CASCADE_HEIGHT(0),
    .CLOCKING_MODE("common_clock"),
    .ECC_MODE("no_ecc"),
    .MEMORY_INIT_FILE("none"),
    .MEMORY_INIT_PARAM("0"),
    .MEMORY_OPTIMIZATION("true"),
    .MEMORY_PRIMITIVE("auto"),
    .MEMORY_SIZE(32768),
    .MESSAGE_CONTROL(0),
    .READ_DATA_WIDTH_B(32),
    .READ_LATENCY_B(2),
    .READ_RESET_VALUE_B("0"),
    .RST_MODE_A("SYNC"),
    .RST_MODE_B("SYNC"),
    .SIM_ASSERT_CHK(1),
    .USE_EMBEDDED_CONSTRAINT(0),
    .USE_MEM_INIT(0),
    .WAKEUP_TIME("disable_sleep"),
    .WRITE_DATA_WIDTH_A(32),
    .WRITE_MODE_B("read_first")
  ) mem (
    .clkb           (aclk                         ), //i
    .rstb           (mem_rstb                     ), //i
    .enb            (io_read_cmd_valid            ), //i
    .regceb         (io_read_cmd_valid            ), //i
    .addrb          (io_read_cmd_payload[9:0]     ), //i
    .doutb          (mem_doutb[31:0]              ), //o
    .sbiterrb       (mem_sbiterrb                 ), //o
    .dbiterrb       (mem_dbiterrb                 ), //o
    .clka           (aclk                         ), //i
    .ena            (io_write_valid               ), //i
    .wea            (io_writeMask[3:0]            ), //i
    .addra          (io_write_payload_address[9:0]), //i
    .dina           (io_write_payload_data[31:0]  ), //i
    .injectsbiterra (1'b0                         ), //i
    .injectdbiterra (1'b0                         ), //i
    .sleep          (1'b0                         )  //i
  );
  assign mem_rstb = (! aresetn);
  assign io_read_rsp = mem_doutb;

endmodule

