          dataVec_23 <= io_push_2_payload;
        end
        if(_zz_3[24]) begin
          dataVec_24 <= io_push_2_payload;
        end
        if(_zz_3[25]) begin
          dataVec_25 <= io_push_2_payload;
        end
        if(_zz_3[26]) begin
          dataVec_26 <= io_push_2_payload;
        end
        if(_zz_3[27]) begin
          dataVec_27 <= io_push_2_payload;
        end
        if(_zz_3[28]) begin
          dataVec_28 <= io_push_2_payload;
        end
        if(_zz_3[29]) begin
          dataVec_29 <= io_push_2_payload;
        end
        if(_zz_3[30]) begin
          dataVec_30 <= io_push_2_payload;
        end
        if(_zz_3[31]) begin
          dataVec_31 <= io_push_2_payload;
        end
      end
      pushPtr <= (pushPtr + _zz_pushPtr);
      if(when_MultiPortFIFOVec_l156) begin
        isRisingOccupancy <= (popCount < pushCount);
      end
      if(recover) begin
        pushPtr <= popPtr;
        isRisingOccupancy <= 1'b1;
      end
    end
  end

  always @(posedge aclk) begin
    io_pop_0_payload <= _zz_io_pop_0_payload;
    io_pop_1_payload <= _zz_io_pop_1_payload;
    io_pop_2_payload <= _zz_io_pop_2_payload;
    if(when_MultiPortFIFOVec_l147) begin
      if(when_MultiPortFIFOVec_l149) begin
        io_pop_0_payload <= io_push_0_payload;
      end
      if(when_MultiPortFIFOVec_l149_1) begin
        io_pop_1_payload <= io_push_0_payload;
      end
      if(when_MultiPortFIFOVec_l149_2) begin
        io_pop_2_payload <= io_push_0_payload;
      end
    end
    if(when_MultiPortFIFOVec_l147_1) begin
      if(when_MultiPortFIFOVec_l149_3) begin
        io_pop_1_payload <= io_push_1_payload;
      end
      if(when_MultiPortFIFOVec_l149_4) begin
        io_pop_2_payload <= io_push_1_payload;
      end
    end
    if(when_MultiPortFIFOVec_l147_2) begin
      if(when_MultiPortFIFOVec_l149_5) begin
        io_pop_2_payload <= io_push_2_payload;
      end
    end
  end


endmodule

module CorrelatingPredictor (
  input               io_read_enable,
  input      [31:0]   io_read_nextPC,
  output     [1:0]    io_read_predCounters_0,
  output     [1:0]    io_read_predCounters_1,
  output     [1:0]    io_read_predCounters_2,
  output     [1:0]    io_read_predCounters_3,
  output     [1:0]    io_read_globalCounters_0,
  output     [1:0]    io_read_globalCounters_1,
  output     [1:0]    io_read_globalCounters_2,
  output     [1:0]    io_read_globalCounters_3,
  output     [1:0]    io_read_bimodalCounters_0,
  output     [1:0]    io_read_bimodalCounters_1,
  output     [1:0]    io_read_bimodalCounters_2,
  output     [1:0]    io_read_bimodalCounters_3,
  output     [1:0]    io_read_chooserCounters_0,
  output     [1:0]    io_read_chooserCounters_1,
  output     [1:0]    io_read_chooserCounters_2,
  output     [1:0]    io_read_chooserCounters_3,
  output reg [3:0]    io_read_predTaken,
  output     [4:0]    io_read_globalHistory,
  input               io_updateGHR_valid,
  input      [4:0]    io_updateGHR_payload,
  input               io_write_valid,
  input      [31:0]   io_write_payload_pc,
  input      [4:0]    io_write_payload_ghr,
  input      [1:0]    io_write_payload_newCounter,
  input      [1:0]    io_write_payload_newBimodalCounter,
  input      [1:0]    io_write_payload_newChooserCounter,
  input               aclk,
  input               aresetn
);

  wire       [12:0]   pht_io_read_cmd_payload;
  wire       [12:0]   pht_io_write_payload_address;
  reg        [1:0]    pht_io_write_payload_data_0;
  wire       [11:0]   tournamentPht_io_read_cmd_payload;
  wire       [11:0]   tournamentPht_io_write_payload_address;
  reg        [3:0]    tournamentPht_io_write_payload_data_0;
  wire       [1:0]    pht_io_read_rsp_0;
  wire       [1:0]    pht_io_read_rsp_1;
  wire       [1:0]    pht_io_read_rsp_2;
  wire       [1:0]    pht_io_read_rsp_3;
  wire       [3:0]    tournamentPht_io_read_rsp_0;
  wire       [3:0]    tournamentPht_io_read_rsp_1;
  wire       [3:0]    tournamentPht_io_read_rsp_2;
  wire       [3:0]    tournamentPht_io_read_rsp_3;
  reg        [4:0]    ghr;
  wire       [4:0]    nextGHR;

  ReorderCacheRAM_1 pht (
    .aclk                     (aclk                              ), //i
    .aresetn                  (aresetn                           ), //i
    .io_read_cmd_valid        (io_read_enable                    ), //i
    .io_read_cmd_payload      (pht_io_read_cmd_payload[12:0]     ), //i
    .io_read_rsp_0            (pht_io_read_rsp_0[1:0]            ), //o
    .io_read_rsp_1            (pht_io_read_rsp_1[1:0]            ), //o
    .io_read_rsp_2            (pht_io_read_rsp_2[1:0]            ), //o
    .io_read_rsp_3            (pht_io_read_rsp_3[1:0]            ), //o
    .io_write_valid           (io_write_valid                    ), //i
    .io_write_payload_address (pht_io_write_payload_address[12:0]), //i
    .io_write_payload_data_0  (pht_io_write_payload_data_0[1:0]  ), //i
    .io_write_payload_data_1  (2'bxx                             ), //i
    .io_write_payload_data_2  (2'bxx                             ), //i
    .io_write_payload_data_3  (2'bxx                             ), //i
    .io_write_payload_mask    (4'b0001                           )  //i
  );
  ReorderCacheRAM_2 tournamentPht (
    .aclk                     (aclk                                        ), //i
    .aresetn                  (aresetn                                     ), //i
    .io_read_cmd_valid        (io_read_enable                              ), //i
    .io_read_cmd_payload      (tournamentPht_io_read_cmd_payload[11:0]     ), //i
    .io_read_rsp_0            (tournamentPht_io_read_rsp_0[3:0]            ), //o
    .io_read_rsp_1            (tournamentPht_io_read_rsp_1[3:0]            ), //o
    .io_read_rsp_2            (tournamentPht_io_read_rsp_2[3:0]            ), //o
    .io_read_rsp_3            (tournamentPht_io_read_rsp_3[3:0]            ), //o
    .io_write_valid           (io_write_valid                              ), //i
    .io_write_payload_address (tournamentPht_io_write_payload_address[11:0]), //i
    .io_write_payload_data_0  (tournamentPht_io_write_payload_data_0[3:0]  ), //i
    .io_write_payload_data_1  (4'bxxxx                                     ), //i
    .io_write_payload_data_2  (4'bxxxx                                     ), //i
    .io_write_payload_data_3  (4'bxxxx                                     ), //i
    .io_write_payload_mask    (4'b0001                                     )  //i
  );
  assign io_read_globalHistory = ghr;
  assign nextGHR = (io_updateGHR_valid ? io_updateGHR_payload : ghr);
  assign pht_io_read_cmd_payload = {nextGHR,io_read_nextPC[9 : 2]};
  assign io_read_globalCounters_0 = pht_io_read_rsp_0;
  assign io_read_globalCounters_1 = pht_io_read_rsp_1;
  assign io_read_globalCounters_2 = pht_io_read_rsp_2;
  assign io_read_globalCounters_3 = pht_io_read_rsp_3;
  assign tournamentPht_io_read_cmd_payload = io_read_nextPC[13 : 2];
  assign io_read_bimodalCounters_0 = tournamentPht_io_read_rsp_0[1 : 0];
  assign io_read_chooserCounters_0 = tournamentPht_io_read_rsp_0[3 : 2];
  assign io_read_bimodalCounters_1 = tournamentPht_io_read_rsp_1[1 : 0];
  assign io_read_chooserCounters_1 = tournamentPht_io_read_rsp_1[3 : 2];
  assign io_read_bimodalCounters_2 = tournamentPht_io_read_rsp_2[1 : 0];
  assign io_read_chooserCounters_2 = tournamentPht_io_read_rsp_2[3 : 2];
  assign io_read_bimodalCounters_3 = tournamentPht_io_read_rsp_3[1 : 0];
  assign io_read_chooserCounters_3 = tournamentPht_io_read_rsp_3[3 : 2];
  assign io_read_predCounters_0 = (io_read_chooserCounters_0[1] ? io_read_globalCounters_0 : io_read_bimodalCounters_0);
  always @(*) begin
    io_read_predTaken[0] = io_read_predCounters_0[1];
    io_read_predTaken[1] = io_read_predCounters_1[1];
    io_read_predTaken[2] = io_read_predCounters_2[1];
    io_read_predTaken[3] = io_read_predCounters_3[1];
  end

  assign io_read_predCounters_1 = (io_read_chooserCounters_1[1] ? io_read_globalCounters_1 : io_read_bimodalCounters_1);
  assign io_read_predCounters_2 = (io_read_chooserCounters_2[1] ? io_read_globalCounters_2 : io_read_bimodalCounters_2);
  assign io_read_predCounters_3 = (io_read_chooserCounters_3[1] ? io_read_globalCounters_3 : io_read_bimodalCounters_3);
  assign pht_io_write_payload_address = {io_write_payload_ghr,io_write_payload_pc[9 : 2]};
  always @(*) begin
    pht_io_write_payload_data_0 = 2'bxx;
    pht_io_write_payload_data_0 = io_write_payload_newCounter;
  end

  assign tournamentPht_io_write_payload_address = io_write_payload_pc[13 : 2];
  always @(*) begin
    tournamentPht_io_write_payload_data_0 = 4'bxxxx;
    tournamentPht_io_write_payload_data_0 = {io_write_payload_newChooserCounter,io_write_payload_newBimodalCounter};
  end

  always @(posedge aclk or negedge aresetn) begin
    if(!aresetn) begin
      ghr <= 5'h0;
    end else begin
      if(io_updateGHR_valid) begin
        ghr <= io_updateGHR_payload;
      end
    end
  end


endmodule

